import React from 'react';
import { graphql } from 'gatsby';
import PropTypes from 'prop-types';
import { Layout, Hero, About, Jobs, Education, Skills, Featured, Projects, Certifications, Contact } from '@components';
import styled from 'styled-components';
import { Main } from '@styles';
import skillOrder from '../../content/skills/robo/skillOrder.json';
import projectOrder from '../../content/featured/robo/projectOrder.json';

const StyledMainContainer = styled(Main)`
  counter-reset: section;
`;

const RoboProfilePage = ({ location, data }) => {
  // Destructure data for easy access and optional rendering
  const {
    hero,
    about,
    jobs,
    education,
    featured,
    projects,
    skills,
    certifications,
    contact,
  } = data;

  return (
    <Layout location={location}>
      <StyledMainContainer className="fillHeight">
        {hero && <Hero data={hero.edges} />}
        {about && <About data={about.edges} />}
        {jobs && <Jobs data={jobs.edges} />}
        {education && <Education data={education.edges} />}
        {featured && <Featured data={featured.edges} projectOrder={projectOrder} />}
        {projects && <Projects data={projects.edges} />}
        {skills && <Skills skillsData={skills.edges} skillOrder={skillOrder} />}
        {certifications && <Certifications data={certifications.edges} />}
        {contact && <Contact data={contact.edges} />}
      </StyledMainContainer>
    </Layout>
  );
};

RoboProfilePage.propTypes = {
  location: PropTypes.shape({
    pathname: PropTypes.string,
  }).isRequired,
  data: PropTypes.shape({
    hero: PropTypes.object,
    about: PropTypes.object,
    jobs: PropTypes.object,
    education: PropTypes.object,
    featured: PropTypes.object,
    projects: PropTypes.object,
    skills: PropTypes.object,
    certifications: PropTypes.object,
    contact: PropTypes.object,
  }).isRequired,
};

export default RoboProfilePage;


export const roboProfilePageQuery = graphql`
  {
    hero: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/hero/robo/" } }) {
      edges {
        node {
          frontmatter {
            title
            name
            subtitle
            buttonText
          }
          html
        }
      }
    }

    about: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/about/robo/" } }) {
      edges {
        node {
          frontmatter {
            title
            avatar {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            skills
          }
          html
        }
      }
    }

    jobs: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/jobs/" }
        frontmatter: { showInExperience: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            company
            shortname
            location
            range
            url
            tech
            logo {
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    education: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/education/" }
        frontmatter: { showInEducation: { eq: true } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            school
            shortname
            programme
            score
            location
            range
            url
            logo{
              childImageSharp {
              gatsbyImageData(
                width: 700
                quality: 90
                placeholder: DOMINANT_COLOR
                layout: CONSTRAINED
              )
            }
            }
          }
          html
        }
      }
    }

    featured: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/robo/" }
        frontmatter: { showInFeatured: { eq: true } }
      }
    ) {
      edges {
        node {
          frontmatter {
            title
            imageCarousel {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
            gifCarousel
            tech
            github
            drive
            external
            youtube
            tags
          }
          html
        }
      }
    }

    projects: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/featured/robo/" }
        frontmatter: { showInProjects: { eq: true }, showInFeatured: { eq: false } }
      }
      sort: {frontmatter: {date: DESC}}
    ) {
      edges {
        node {
          frontmatter {
            title
            tech
            github
            external
          }
          html
        }
      }
    }

    certifications: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/certifications/robo/" }
        frontmatter: { showInCertifications: { eq: true } }
      }
      sort: {frontmatter: {priority: ASC}}
    ) {
      edges {
        node {
          frontmatter {
            course
            institute
            company
            github
            external
            tech
          }
          html
        }
      }
    }

    skills: allMarkdownRemark(
      filter: {
        fileAbsolutePath: { regex: "/skills/types/" }
        frontmatter: { showInSkills: { eq: true } }
      }
    ) {
      edges {
        node {
          frontmatter {
            name
            logo {
              childImageSharp {
                gatsbyImageData(
                  width: 700
                  quality: 90
                  placeholder: DOMINANT_COLOR
                  layout: CONSTRAINED
                )
              }
            }
          }
          html
        }
      }
    }

    contact: allMarkdownRemark(filter: { fileAbsolutePath: { regex: "/contact/" } }) {
      edges {
        node {
          frontmatter {
            title
            buttonText
          }
          html
        }
      }
    }
  }
`;